import { useState, FormEvent } from 'react';
import { JxInputField, JxSelect, JxSwitch, JxButton, JxAlert } from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const roleOptions = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const emailTouched = email.length > 0;
  const isEmailValid = EMAIL_PATTERN.test(email);
  const emailError = emailTouched && !isEmailValid ? 'Укажите адрес в формате имя@домен' : undefined;
  const canSubmit = isEmailValid;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!canSubmit) return;
    setSubmitted(true);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px', maxWidth: '360px' }}>
      {submitted && (
        <JxAlert intent="success" title="Приглашение отправлено" onClick={undefined}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '12px' }}>
            <span>{email} приглашён(а) в команду.</span>
            <JxButton
              variant="ghost"
              size="sm"
              iconOnly
              aria-label="Закрыть сообщение"
              onClick={() => setSubmitted(false)}
            >
              ×
            </JxButton>
          </div>
        </JxAlert>
      )}

      <form onSubmit={submit} style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
        <JxInputField
          label="Электронная почта"
          type="email"
          required
          placeholder="name@company.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          errorText={emailError}
          helperText={!emailError ? 'На этот адрес придёт приглашение в команду' : undefined}
        />

        <JxSelect
          label="Роль"
          options={roleOptions}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление о приглашении"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <JxButton type="submit" variant="primary" disabled={!canSubmit}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

